SELECT w.* FROM {s}.init_operation o LEFT JOIN LATERAL (SELECT 1 AS present,canonical_position,device,inode,evidence,host_path FROM (SELECT canonical_position,device,inode,evidence,host_path,sum(octet_length(host_path)+68) OVER (ORDER BY canonical_position) AS run,row_number() OVER (ORDER BY canonical_position) AS n FROM (SELECT canonical_position,device,inode,evidence,host_path FROM {s}.init_host_file WHERE operation_id=$1::bigint AND canonical_position>$3::bigint ORDER BY canonical_position LIMIT $4::bigint) l) j WHERE n=1 OR run<=$5::bigint) w ON true WHERE o.operation_id=$1::bigint AND o.owner_epoch=$2::bigint
